static const float svm_intercept[SVM_PAIR_COUNT] = {0.807541728f,0.001586359f,1.38934998f,0.924807952f,-0.719689062f,0.168844395f,0.458660464f,1.11917181f,0.926620684f,0.346823164f};
#define SVM_MODEL_BYTES (sizeof(svm_n_support) + sizeof(svm_support_start) + sizeof(svm_support_vectors) + sizeof(svm_dual_coef) + sizeof(svm_intercept))
static inline int svm_predict(const float *features) {
    static float kvalue[SVM_SUPPORT_VECTOR_COUNT];
    for (int k = 0; k < SVM_SUPPORT_VECTOR_COUNT; ++k) {
        float distance = 0.0f;
        for (int f = 0; f < SVM_FEATURE_COUNT; ++f) {
            float delta = features[f] - (float)svm_support_vectors[k][f] / SVM_SV_SCALE;
            distance += delta * delta;
        }
        kvalue[k] = expf(-SVM_GAMMA * distance);
    }

    int votes[SVM_CLASS_COUNT] = {0};
    int pair = 0;
    for (int i = 0; i < SVM_CLASS_COUNT; ++i) {
        const int start_i = svm_support_start[i];
        const int count_i = svm_n_support[i];
        for (int j = i + 1; j < SVM_CLASS_COUNT; ++j, ++pair) {
            const int start_j = svm_support_start[j];
            const int count_j = svm_n_support[j];
            float sum = svm_intercept[pair];
            for (int k = 0; k < count_i; ++k) {
                sum += ((float)svm_dual_coef[j - 1][start_i + k] / SVM_DUAL_COEF_SCALE) * kvalue[start_i + k];
            }
            for (int k = 0; k < count_j; ++k) {
                sum += ((float)svm_dual_coef[i][start_j + k] / SVM_DUAL_COEF_SCALE) * kvalue[start_j + k];
            }
            if (sum > 0.0f) ++votes[i]; else ++votes[j];
        }
    }
    int best = 0;
    for (int i = 1; i < SVM_CLASS_COUNT; ++i) {
        if (votes[i] > votes[best]) best = i;
    }
    return best;
}
